-- ============================================================================
-- Campus Job Posting System (KLD Campus Hire)
-- Comprehensive 3NF Normalized Sample Seed Data (Fake / Demo Data)
-- Database: campus_job_portal
-- ============================================================================

USE `campus_job_portal`;

-- Disable foreign key checks while inserting relational mock data
SET FOREIGN_KEY_CHECKS = 0;


-- 1. Table: categories
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- 2. Table: users (Core Authentication & Identity Supertype)
-- ----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `email`=VALUES(`email`);

-- ----------------------------------------------------------------------------
-- 2.1 Table: student_profiles (Student Subtype)
-- ----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `student_id`=VALUES(`student_id`);

-- ----------------------------------------------------------------------------
-- 2.2 Table: employer_profiles (Employer Subtype)
-- ----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `organization_name`=VALUES(`organization_name`);


-- ----------------------------------------------------------------------------
-- 3. Table: jobs (Normalized Requisition Header)
-- ----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);


-- ----------------------------------------------------------------------------
-- 4. Table: applications (Pure Junction & Hiring Workflow State)
-- ----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `status`=VALUES(`status`);


-- ----------------------------------------------------------------------------
-- 5. Table: profile_requests (Student COR Profile Correction Queue)
-- ----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `status`=VALUES(`status`);


-- ----------------------------------------------------------------------------
-- 6. Table: updates (Career Center News & Policy Announcements)
-- ----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);


-- -- 7. Table: devblogs
-- ----------------------------------------------------------------------------

-- Re-enable foreign key checks
SET FOREIGN_KEY_CHECKS = 1;
