INSERT INTO `categories` (`id`, `name`, `slug`, `icon`, `description`, `theme`, `badge_tag`, `badge_icon`, `job_count`, `hourly_range`, `image`, `popular_roles`) VALUES (1, 'IT & Technical Support', 'it-technical-support', 'bi-laptop', 'IT lab maintenance, technical troubleshooting, network setup, compiler installations, and student workstation support.', 'kld-green', 'Most In-Demand', 'bi-fire', 4, '₱85.00 / hr', 'assets/img/categories/cat-tech.jpg', '[\"Computer Lab Assistant\",\"Network Technician\",\"MIS Helpdesk\",\"Workstation Support\"]') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`);
