INSERT INTO `categories` (`id`, `name`, `slug`, `icon`, `description`, `theme`, `badge_tag`, `badge_icon`, `job_count`, `hourly_range`, `image`, `popular_roles`) VALUES (4, 'Science & Computer Lab Assistant', 'science-computer-lab-assistant', 'bi-radioactive', 'Science & medical laboratory apparatus preparation, glassware autoclaving, chemical inventory logging, and safety protocol enforcement.', 'kld-green', 'Science & Health', 'bi-moisture', 2, '₱85.00 / hr', 'assets/img/categories/cat-lab.jpg', '[\"Medical Lab Aid\",\"Apparatus Prep\",\"Inventory Custodian\"]') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`);
INSERT INTO `categories` (`id`, `name`, `slug`, `icon`, `description`, `theme`, `badge_tag`, `badge_icon`, `job_count`, `hourly_range`, `image`, `popular_roles`) VALUES (5, 'Peer Tutor', 'peer-tutor', 'bi-mortarboard', '1-on-1 and small group academic tutoring in mathematics, coding algorithms, discrete structures, sciences, and exam preparation.', 'kld-green', 'Academic Mentoring', 'bi-award-fill', 3, '₱100.00 / hr', 'assets/img/categories/cat-tutor.jpg', '[\"Math & Calc Tutor\",\"Programming Mentor\",\"Peer Coach\"]') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`);
