INSERT INTO `jobs` (`id`, `title`, `department`, `category_id`, `employer_id`, `job_type`, `work_setup`, `location`, `pay_rate`, `pay_type`, `hours_per_week`, `vacancies`, `slots_total`, `slots_filled`, `deadline`, `status`, `image`, `tags`, `badges`, `description`, `responsibilities`, `qualifications`, `created_at`, `updated_at`) VALUES 
(1, 'Computer Lab Technical Assistant', 'Management Information Systems (MIS)', 1, 4, 'Student Assistant', 'On-Campus', 'Main Campus · ICT Center 302', '₱85.00 / hour', 'Hourly', '15 - 20 hrs/week', 5, 5, 3, '2026-11-15', 'active', 'assets/img/categories/cat-tech.jpg', '["Flexible Schedule","Urgent","Tech Support","University Office"]', '["Student Assistant","Flexible Schedule","Urgent"]', 'Assist the MIS team in maintaining student computer laboratories, performing routine hardware/software troubleshooting, monitoring laboratory usage, and assisting students during hands-on classes.', '["Check PC hardware and peripheral operability before daily lab sessions.","Assist students and professors with network login, compiler installations, and software tools.","Maintain cleanliness and enforce lab safety regulations.","Log hardware faults and escalate critical network disruptions to senior network engineers."]', '["Currently enrolled 2nd to 4th year BSIS, BSCS, or BSDS student.","General Weighted Average (GWA) of 2.25 or better.","Basic knowledge in PC troubleshooting, Windows/Linux OS, and local networking.","Responsible, punctual, and equipped with strong interpersonal skills."]', '2026-08-20 00:00:00', '2026-09-03 07:53:52'),
(2, 'Student Records & Archival Assistant', 'Office of the University Registrar', 3, 3, 'Student Assistant', 'On-Campus', 'Admin Building · Room 104', '₱80.00 / hour', 'Hourly', '10 - 15 hrs/week', 4, 4, 2, '2026-11-20', 'active', 'assets/img/jobs/job-02.jpg', '["Part-Time","Office Work","University Office"]', '["Student Assistant","Part-time"]', 'Support the University Registrar in organizing student records, encoding registration documents, sorting physical course binders, and assisting visitors at the information desk.', '["Scan and index student transcript documents into the digital archive.","Assist in receiving and sorting incoming student clearance and graduation applications.","Organize student physical 201 filing cabinets.","Provide courteous frontline queue direction during peak enrollment periods."]', '["Open to all undergraduate programs in good standing.","Proficient in Microsoft Excel, Word, and Google Workspace.","High attention to detail and strong adherence to data privacy and confidentiality.","Must have at least 3 consecutive free hours during weekdays."]', '2026-08-21 00:00:00', '2026-09-03 07:53:52'),
(3, 'Digital Cataloging & Library Aid', 'University Library Services', 2, 3, 'Student Assistant', 'On-Campus', 'Library Wing · 2nd Floor', '₱80.00 / hour', 'Hourly', '12 - 18 hrs/week', 3, 3, 1, '2026-11-25', 'active', 'assets/img/jobs/job-03.jpg', '["Quiet Environment","Study Friendly","University Office"]', '["Student Assistant","Flexible Schedule"]', 'Assist librarians with book circulation, Dewey Decimal sorting, barcode scanning, thesis collection archiving, and patron assistance in the quiet study hub.', '["Check in and check out library reference books using the barcode circulation scanner.","Shelve books according to cataloging standards and perform shelf-reading.","Assist students and faculty in navigating OPAC (Online Public Access Catalog).","Monitor study areas to ensure a conducive, quiet learning atmosphere."]', '["Bona fide student with at least 1 remaining academic year.","Diligent, polite, organized, and fond of reading and books.","Can commit to either morning (8:00 AM - 12:00 PM) or afternoon (1:00 PM - 5:00 PM) shifts."]', '2026-08-22 00:00:00', '2026-09-03 07:53:52'),
(4, 'Peer Tutor - Linear Algebra & Discrete Math', 'Institute of Science and Mathematics (ISM)', 5, 4, 'Peer Tutor', 'On-Campus', 'Learning Commons · Room 204', '₱100.00 / hour', 'Hourly', '8 - 12 hrs/week', 2, 2, 1, '2026-12-05', 'active', 'assets/img/jobs/job-04.jpg', '["High Pay","Academic","Peer Tutor"]', '["Peer Tutor","Part-time","Flexible Schedule"]', 'Provide scheduled one-on-one and small group peer tutoring for 1st and 2nd year students struggling with Linear Algebra, Discrete Mathematics, and Calculus.', '["Conduct structured 1-hour tutorial sessions according to student bookings.","Prepare sample problem worksheets and concept explanation summaries.","Maintain student attendance logs and report progress to the Department Chair.","Encourage active problem solving and confidence building."]', '["Currently enrolled in BSCS, BSIS, BSDS, or BSCE.","Must have earned a final grade of 1.50 or higher in Linear Algebra and Discrete Math.","Patient, articulate, and passionate about teaching math concepts.","Endorsement letter from an ISM faculty member is a plus."]', '2026-08-23 00:00:00', '2026-09-03 07:53:52'),
(5, 'Junior Web Developer Intern (OJT)', 'Software & Web Development Partner', 1, 6, 'Internship / OJT', 'Hybrid', 'Dasma Tech Park / Hybrid (Near Campus)', '₱120.00 / hour', 'Hourly', '15 - 20 hrs/week', 3, 3, 1, '2026-12-12', 'active', 'assets/img/jobs/job-05.jpg', '["Internship","Web Dev","Approved Partner","High Pay"]', '["Internship \/ OJT","Approved Partner","Hybrid"]', 'Join an accredited industry technology partner to develop real-world client web applications using HTML/CSS, JavaScript, PHP/Node, and modern API integrations. Perfect for 3rd and 4th year computing students seeking academic OJT credits.', '["Collaborate with lead developers in building responsive UI layouts and backend APIs.","Participate in daily agile sprint standups and code reviews.","Debug cross-browser frontend issues and write clean, modular documentation.","Submit weekly supervisor evaluations for college OJT accreditation."]', '["Currently enrolled in BSIS, BSCS, or related technical degrees.","Familiar with Git, JavaScript, PHP, and responsive CSS frameworks.","Able to commit 15–20 hours/week in a hybrid setup (2 days on-site, 2 days remote).","Official endorsement form from the KLD Practicum Coordinator."]', '2026-08-24 00:00:00', '2026-09-03 07:53:52'),
(6, 'Part-Time Social Media & Content Creator', 'Creative & Digital Media Partner', 3, 7, 'Part-Time Job', 'Near-Campus', 'Creative Hub Center (Near Campus)', '₱110.00 / hour', 'Hourly', '12 - 16 hrs/week', 2, 2, 0, '2026-12-18', 'active', 'assets/img/jobs/job-06.jpg', '["Part-Time","Creative","Approved Partner"]', '["Part-Time Job","Approved Partner","Creative"]', 'Create engaging short-form TikTok/Reels video content, design Canva graphics for local marketing campaigns, and assist in copywriting for an approved regional media partner.', '["Shoot and edit engaging vertical video content highlighting youth lifestyle and education.","Design branded social media post carousels and promotional posters.","Monitor engagement metrics and respond to community comments under guidance.","Ensure all published material adheres to university partner ethical standards."]', '["Passionate about video editing (CapCut, Premiere, or Canva).","Creative eye for typography, layouts, and storytelling.","Flexible schedule tailored around class timetables."]', '2026-08-25 00:00:00', '2026-09-03 07:53:52'),
(7, 'Student Barista & Customer Service Crew', 'Campus Food Concessionaire Partner', 3, 8, 'Part-Time Job', 'On-Campus', 'University Student Pavilion & Food Arcade', '₱90.00 / hour', 'Hourly', '10 - 15 hrs/week', 3, 3, 1, '2026-12-20', 'active', 'assets/img/jobs/job-07.jpg', '["Part-Time","Customer Service","On-Campus"]', '["Part-Time Job","On-Campus","Flexible Schedule"]', 'Learn specialty espresso brewing, assist in counter POS cashiering, and provide friendly hospitality at the official campus student cafe located inside the Student Pavilion.', '["Prepare espresso drinks, cold brews, and seasonal refreshments following recipes.","Operate touch-screen point-of-sale register and issue official receipts.","Maintain strict cleanliness and food safety sanitation in the dining area.","Coordinate with supervisor for weekly shift planning aligned with class schedules."]', '["Cheerful, friendly demeanor with strong work ethic.","No prior barista experience required; complete paid on-site training provided.","Available for morning (7:30 AM - 11:30 AM) or afternoon (1:30 PM - 5:30 PM) slots."]', '2026-08-26 00:00:00', '2026-09-03 07:53:52'),
(8, 'Science & Computer Lab Assistant', 'College of Science & Laboratories', 4, 5, 'Student Assistant', 'On-Campus', 'Science Wing · Lab 101', '₱85.00 / hour', 'Hourly', '12 - 16 hrs/week', 4, 4, 2, '2026-12-10', 'active', 'assets/img/jobs/job-08.jpg', '["Science","Lab Prep","University Office"]', '["Student Assistant","Urgent"]', 'Assist laboratory custodians in preparing glassware, non-hazardous reagent solutions, setting up microscope benches, and conducting equipment sanitation.', '["Distribute apparatus to students before experiments and inspect returns for breakage.","Wash and autoclave laboratory glassware following strict chemical hygiene procedures.","Maintain reagent inventory and log chemical consumption.","Ensure proper waste segregation and disposal compliance."]', '["Enrolled in Allied Science, Computer, or Engineering programs.","Passed Chemistry/Lab fundamentals with high marks.","Strict compliance with lab safety goggles, lab coat, and chemical handling guidelines."]', '2026-08-25 00:00:00', '2026-09-03 07:53:52'),
(9, 'Gymnasium Equipment Custodian & Court Monitor', 'Student Affairs & Services Office (SASO)', 6, 3, 'Student Assistant', 'On-Campus', 'Campus Gymnasium & Sports Complex', '₱85.00 / hour', 'Hourly', '10 - 15 hrs/week', 3, 3, 1, '2026-11-30', 'active', 'assets/img/jobs/job-09.jpg', '["Sports","Equipment Logistics","University Office","On-Campus"]', '["Student Assistant","Flexible Schedule"]', 'Assist the Athletics & Sports Development Office in issuing and logging sports equipment, monitoring gymnasium court reservations, ensuring court safety regulations, and maintaining equipment cleanliness.', '["Inspect and distribute balls, nets, and athletics equipment before varsity practice and intramural games.","Maintain digital check-in/check-out logs for student equipment borrowings.","Monitor court bookings and enforce footwear and gymnasium safety rules.","Report damaged equipment and assist in periodic inventory audits."]', '["Currently enrolled KLD student in good academic standing.","Punctual, physically active, and responsible with university property.","Available for afternoon shifts (1:00 PM - 5:00 PM) or weekend sports events.","Previous involvement in sports or athletics is an advantage but not required."]', '2026-08-27 00:00:00', '2026-09-03 07:53:52'),
(10, 'Intramural Tournament Scorekeeper & Athletics Aide', 'Student Affairs & Services Office (SASO)', 6, 3, 'Student Assistant', 'On-Campus', 'University Covered Courts & Field', '₱85.00 / hour', 'Hourly', '8 - 12 hrs/week', 2, 2, 0, '2026-12-05', 'active', 'assets/img/jobs/job-10.jpg', '["Scorekeeper","Intramurals","University Office","High Pay"]', '["Student Assistant","Part-Time","Flexible Schedule"]', 'Support campus sports tournaments and intramural leagues through official digital scorekeeping, scoreboard operation, equipment staging, and referee table coordination.', '["Operate the electronic scoreboard and official timer during scheduled tournament matches.","Record points, fouls, timeouts, and player statistics on official score sheets.","Coordinate with game officials and tournament directors to ensure smooth match flow.","Assist in trophy staging, court setup, and post-game record filing."]', '["Enrolled student with GWA of 2.50 or better.","High focus, attention to detail, and familiarity with basketball, volleyball, or badminton rules.","Ability to work calmly under the excitement of live competitive games.","Willing to work flexible schedules during intramural tournament weeks."]', '2026-08-28 00:00:00', '2026-09-03 07:53:52')
INSERT INTO `applications` (`id`, `job_id`, `student_id`, `cover_letter`, `availability`, `resume_file`, `study_load_file`, `status`, `interview_date`, `interview_time`, `interview_venue`, `supervisor_notes`, `applied_at`, `updated_at`) VALUES 
(1, 1, 1, 'I am eager to apply for the Computer Lab Technical Assistant position. As a 2nd year BS Information Systems student at KLD, I have solid experience troubleshooting PC hardware, setting up local area networks, and installing development environments. I am enthusiastic about supporting fellow KLD students and keeping our laboratories running smoothly.', '["Monday (1:00 PM - 5:00 PM)","Wednesday (1:00 PM - 5:00 PM)","Friday (8:00 AM - 12:00 PM)"]', 'Juan_Dela_Cruz_Resume.pdf', 'Juan_Dela_Cruz_StudyLoad.pdf', 'interview_scheduled', '2026-08-30', '02:00 PM', 'KLD Tech Building, Room 305 (MIS Office)', 'Strong background in PC troubleshooting. Scheduled for face-to-face technical interview.', '2026-08-22 14:30:00', '2026-08-24 10:00:00'),
(2, 2, 1, 'I would like to offer my clerical and database encoding skills to the Office of the University Registrar at KLD. I am proficient in MS Excel spreadsheets and data archiving.', '["Tuesday (8:00 AM - 12:00 PM)","Thursday (8:00 AM - 12:00 PM)"]', 'Juan_Dela_Cruz_Resume.pdf', 'Juan_Dela_Cruz_StudyLoad.pdf', 'interview_scheduled', '2026-08-28', '02:00 PM', 'KLD Admin Building, 1st Floor, Room 102', 'Application received, awaiting registrar committee evaluation.', '2026-08-24 09:15:00', '2026-08-26 08:40:13'),
(3, 3, 2, 'I am applying for the Library Aid role. I spend a lot of time in the KLD library, have high attention to detail, and can commit to morning shifts.', '["Monday (8:00 AM - 12:00 PM)","Wednesday (8:00 AM - 12:00 PM)"]', 'Maria_Santos_Resume.pdf', 'Maria_Santos_StudyLoad.pdf', 'accepted', '2026-08-23', '10:00 AM', 'KLD Main Library 2nd Floor Office', 'Excellent communication skills and schedule fit. Officially approved for 1st Semester duty.', '2026-08-20 11:00:00', '2026-08-24 16:20:00')
