INSERT INTO `updates` (`id`, `slug`, `title`, `category`, `published_at`, `read_time`, `author_id`, `author_avatar`, `image`, `summary`, `content`, `created_at`, `updated_at`) VALUES 
(1, 'spring-career-fair-welcomes-over-40-campus-offices', 'Spring Career Fair Welcomes Over 40 Campus Offices and Department Laboratories', 'Campus Event', '2026-06-12 09:30:00', '4 min read', 5, 'ES', 'assets/img/updates/update-01.jpg', 'The annual campus career fair connects undergraduate students directly with departmental supervisors for on-campus student assistantship roles and practicum placements.', '<p class="lead text-ink mb-4">The Kolehiyo ng Lungsod ng Dasmariñas (KLD) Career Development &amp; Placement Office officially launched its annual Spring Campus Career Fair at the University Gymnasium, drawing hundreds of undergraduate students eager to secure on-campus assistantship roles and academic practicum placements for the upcoming term.</p><h3 class="h4 fw-bold text-ink mt-4 mb-3">Connecting Classrooms with Real Campus Work</h3><p>More than 40 academic institutes, administrative offices, and specialized campus facilities participated in this year's event. Representatives from the Institute of Computing and Digital Innovation (ICDI), College Library, Management Information Systems (MIS) Unit, and Science Laboratories set up interactive information desks to discuss open positions, day-to-day duties, and eligibility criteria directly with students.</p><div class="card-paper p-4 my-4 bg-cream border-start border-4 border-success"><h4 class="h6 fw-bold text-ink mb-2"><i class="bi bi-lightbulb-fill text-accent me-2"></i>Key Takeaways for Applicants</h4><ul class="mb-0 text-muted-custom small"><li><strong>Direct Supervisor Consultations:</strong> Over 150 student interviews were conducted on-site for immediate term openings.</li><li><strong>Verified Academic Scheduling:</strong> Applicants were matched based on their free hours to prevent academic class overlaps.</li><li><strong>Automated Application Portals:</strong> Students can follow up on their applications directly through the KLD Campus Job Posting System.</li></ul></div><h3 class="h4 fw-bold text-ink mt-4 mb-3">Supervisor Perspectives</h3><p>"Student assistants play a crucial role in maintaining high operational efficiency across our campus libraries and laboratory facilities," said Prof. Arthur Valenzuela. "This event allows us to evaluate not just technical capabilities, but also enthusiasm, communication skills, and reliability."</p><h3 class="h4 fw-bold text-ink mt-4 mb-3">What Students Should Do Next</h3><p>If you attended the fair and submitted your resume, remember to check your <strong>Student Dashboard &gt; My Applications</strong> tab regularly. Supervisors will update application statuses with scheduled interview invites or preliminary acceptance notices within 5 to 7 business days.</p>', '2026-06-12 09:30:00', '2026-06-12 09:30:00'),
(2, 'employer-portal-opens-for-term-1-student-assistantships', 'Employer & Department Portal Opens for Term 1 Student Assistantship Vacancies', 'Hiring Policy', '2026-06-05 14:15:00', '3 min read', 5, 'AV', 'assets/img/updates/update-02.jpg', 'Department heads and laboratory supervisors can now submit student assistant position descriptions, set required schedule slots, and review candidate applications online.', '<p class="lead text-ink mb-4">The Office of Student Affairs &amp; Services (OSAS) has announced the official opening of the Employer &amp; Department Portal for the upcoming academic semester. Faculty supervisors, laboratory custodians, and department administrators can now publish verified job vacancies.</p><h3 class="h4 fw-bold text-ink mt-4 mb-3">Simplified Hiring Workflow for Campus Offices</h3><p>With the new role-based portal, departments can easily configure job requirements, set weekly shift hours, specify necessary skill prerequisites, and review incoming student profiles with one-click evaluation tools. The system ensures full adherence to university labor guidelines and institutional policies.</p><div class="card-paper p-4 my-4 bg-cream border-start border-4 border-success"><h4 class="h6 fw-bold text-ink mb-2"><i class="bi bi-shield-check text-accent me-2"></i>Compliance with the 20-Hour Work Policy</h4><p class="small text-muted-custom mb-0">All posted vacancies are automatically checked to ensure student shifts do not exceed the university's statutory <strong>20-hour maximum per week</strong>, ensuring students maintain optimal focus on academic coursework and examinations.</p></div><h3 class="h4 fw-bold text-ink mt-4 mb-3">How Departments Can Get Started</h3><ol class="text-muted-custom small mb-4"><li>Log into your registered employer account via the <strong>For Employers</strong> portal.</li><li>Click <strong>Post a Vacancy</strong> and select the appropriate position category and required schedule windows.</li><li>Submit for Career Center verification to publish the listing live to all qualified students.</li></ol>', '2026-06-05 14:15:00', '2026-06-05 14:15:00'),
(3, 'interactive-resume-and-interview-workshop', 'Interactive Resume & Interview Workshop Prepares Over 200 Students', 'Workshop', '2026-06-02 11:00:00', '5 min read', 5, 'MO', 'assets/img/updates/update-03.jpg', 'Students learned how to highlight academic achievements, coursework projects, and weekly schedule availability to stand out during campus interviews.', '<p class="lead text-ink mb-4">Over 200 undergraduate students gathered at the Audio-Visual Theater for an intensive interactive workshop focused on building effective student resumes, navigating campus interviews, and presenting course availability confidently.</p><h3 class="h4 fw-bold text-ink mt-4 mb-3">Highlights from the Workshop</h3><p>Unlike corporate resumes that focus on years of full-time experience, student assistantship applications place high emphasis on coursework competency, academic honors, organizational leadership, and reliable time management.</p><div class="card-paper p-4 my-4 bg-cream border-start border-4 border-success"><h4 class="h6 fw-bold text-ink mb-2"><i class="bi bi-journal-text text-accent me-2"></i>Top 3 Resume Tips from the Counselors</h4><ul class="mb-0 text-muted-custom small"><li><strong>Quantify Academic Projects:</strong> Mention real outputs such as laboratory systems built, research papers authored, or campus events coordinated.</li><li><strong>Detail Schedule Transparency:</strong> Clearly outline your class schedule and available vacant hours so supervisors can immediately see shift compatibility.</li><li><strong>Include Faculty References:</strong> Ensure at least one professor or academic advisor can vouch for your punctuality and dedication.</li></ul></div><h3 class="h4 fw-bold text-ink mt-4 mb-3">Mock Interview Breakout Sessions</h3><p>Attendees participated in mock interview simulations with faculty volunteers, practicing responses to behavioral questions regarding conflict resolution, deadline handling, and task prioritization during midterm exam weeks.</p>', '2026-06-02 11:00:00', '2026-06-02 11:00:00'),
(4, 'alumni-peer-mentors-share-strategies-for-balancing-work-and-study', 'Alumni Peer Mentors Share Strategies for Balancing Academics and On-Campus Work', 'Student Success', '2026-05-29 16:45:00', '4 min read', 5, 'KR', 'assets/img/updates/update-04.jpg', 'Graduating seniors and alumni discuss time management routines, academic grade maintenance, and hands-on workplace skills acquired through campus jobs.', '<p class="lead text-ink mb-4">In an inspiring panel session hosted by the Institutional Development Office, four former student assistants turned graduating honor students shared how their on-campus jobs became the foundation for their early career readiness.</p><h3 class="h4 fw-bold text-ink mt-4 mb-3">Real Insights from Past Student Assistants</h3><p>"Working in the university computer laboratory wasn't just about earning an hourly stipend," shared Mark Fernandez (BSIS Batch 2025). "It taught me customer service, server maintenance, troubleshooting under pressure, and how to communicate effectively with department chairs."</p><div class="card-paper p-4 my-4 bg-cream border-start border-4 border-success"><h4 class="h6 fw-bold text-ink mb-2"><i class="bi bi-clock-history text-accent me-2"></i>The 3-Pillar Balance Strategy</h4><ul class="mb-0 text-muted-custom small"><li><strong>Fixed Study Blocks:</strong> Treat study hours as non-negotiable meetings that cannot be rescheduled.</li><li><strong>Proactive Communication:</strong> Inform your supervisor at least two weeks before midterm exam periods so schedules can be adjusted.</li><li><strong>Rest and Well-being:</strong> Take advantage of campus mental health and counseling resources whenever feeling overloaded.</li></ul></div><h3 class="h4 fw-bold text-ink mt-4 mb-3">Building Professional Networks on Campus</h3><p>Panelists emphasized that on-campus supervisors often become a student's strongest references for industry jobs, scholarship applications, and graduate school recommendations.</p>', '2026-05-29 16:45:00', '2026-05-29 16:45:00'),
(5, 'understanding-campus-work-regulations-20-hour-limit', 'Understanding Campus Work Regulations: The 20-Hour Weekly Limit Explained', 'Regulations', '2026-05-20 10:00:00', '3 min read', 5, 'RD', 'assets/img/updates/update-05.jpg', 'A complete guide on student work limits, rest periods during examination periods, and maintaining Dean's List eligibility while employed on campus.', '<p class="lead text-ink mb-4">To safeguard academic excellence and promote student welfare, Kolehiyo ng Lungsod ng Dasmariñas enforces strict institutional policies governing student assistant workloads and duty hours.</p><h3 class="h4 fw-bold text-ink mt-4 mb-3">The Academic Priority Rule</h3><p>Under university guidelines, a student's academic standing takes supreme priority over any campus employment obligation. Student assistants must maintain regular academic enrollment and a passing General Weighted Average (GWA) to remain eligible for assistantship programs.</p><div class="card-paper p-4 my-4 bg-cream border-start border-4 border-success"><h4 class="h6 fw-bold text-ink mb-2"><i class="bi bi-exclamation-triangle-fill text-accent me-2"></i>Mandatory Work Caps</h4><p class="small text-muted-custom mb-2"><strong>Maximum Working Hours:</strong> Students may not be scheduled for more than 20 hours per week during regular academic terms, or 4 hours per day on class days.</p><p class="small text-muted-custom mb-0"><strong>Exam Week Moratorium:</strong> Assistantship duties are strictly paused or reduced to essential standby during official midterm and final examination schedules.</p></div><h3 class="h4 fw-bold text-ink mt-4 mb-3">Transparent Reporting</h3><p>Supervisors submit digital timecards through the admin portal, allowing the Career Center and Office of Student Affairs to monitor compliance and process monthly stipends accurately.</p>', '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(6, 'peer-tutoring-program-expands-across-stem-and-business', 'Peer Tutoring & Academic Coaching Program Expands Across STEM and Business Courses', 'Academic Support', '2026-05-14 08:30:00', '4 min read', 5, 'BR', 'assets/img/updates/update-06.jpg', 'High-performing 2nd to 4th year students can now apply to become paid peer tutors, supporting fellow classmates in programming, mathematics, and accounting.', '<p class="lead text-ink mb-4">The Institute of Computing and Digital Innovation (ICDI) in partnership with the Career Center has announced the expansion of the campus-wide Peer Tutoring and Academic Coaching Initiative.</p><h3 class="h4 fw-bold text-ink mt-4 mb-3">Empowering Student Mentors</h3><p>Qualified upperclassmen who have achieved grades of 1.75 or higher in core subjects (such as Object-Oriented Programming, Database Systems, Discrete Mathematics, and Financial Accounting) are invited to apply for paid peer tutor positions.</p><div class="card-paper p-4 my-4 bg-cream border-start border-4 border-success"><h4 class="h6 fw-bold text-ink mb-2"><i class="bi bi-award-fill text-accent me-2"></i>Tutor Benefits &amp; Incentives</h4><ul class="mb-0 text-muted-custom small"><li><strong>Competitive Hourly Stipend:</strong> Funded directly through the academic support grant.</li><li><strong>Official Certification:</strong> Receive an official Certificate of Academic Mentorship from the Office of the Vice President for Academic Affairs.</li><li><strong>Flexible Tutoring Hubs:</strong> Conduct 1-on-1 or small group study sessions in the campus learning commons or digital study rooms.</li></ul></div><h3 class="h4 fw-bold text-ink mt-4 mb-3">How to Apply as a Peer Tutor</h3><p>Visit the <strong>Find Jobs</strong> page, filter by category <em>Academic &amp; Tutoring</em>, and submit your application with your Certificate of Registration (COR) and latest academic grade slip.</p>', '2026-05-14 08:30:00', '2026-05-14 08:30:00')
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-14', '14', 'Sealing Demo Backdoors, Unifying Table Flags & Shipping the Accepted-Student Flow', 'September 11, 2026', 'Gated the passwordless demo hooks to loopback-only, fixed an Apply redirect that silently signed guests in as another student, replaced rainbow table pills with a uniform dot-flag system, cut the job-card photo to a single overlay, and shipped an opt-in withdraw-others flow for accepted students — every change proven with curl traces and Playwright screenshots.', '{\"id\":\"day-14\",\"sprint_number\":\"14\",\"sprint_badge\":\"DAY 14 · TRUST HARDENING & PAPER DISCIPLINE\",\"title\":\"Sealing Demo Backdoors, Unifying Table Flags & Shipping the Accepted-Student Flow\",\"date\":\"September 11, 2026\",\"read_time\":\"8 min read\",\"author_name\":\"Alwinson Bustamante\",\"author_role\":\"Lead Developer & System Architect\",\"author_image\":\"assets/img/developers/BUSTAMANTE.jpg\",\"summary_excerpt\":\"Gated the passwordless demo hooks to loopback-only, fixed an Apply redirect that silently signed guests in as another student, replaced rainbow table pills with a uniform dot-flag system, cut the job-card photo to a single overlay, and shipped an opt-in withdraw-others flow for accepted students — every change proven with curl traces and Playwright screenshots.\",\"tags\":[\"Demo Backdoor Gating\",\"Return-To Auth\",\"Cell-Flag System\",\"Accept Flow\",\"De-Pilling\",\"Playwright Proof\"],\"cover_image\":\"assets/img/devblog/day-14.jpg\",\"full_story\":\"<p class=\'lead text-ink fw-semibold\'>September 11 was a trust-and-clarity sprint: every path that could silently sign a visitor in as someone else got sealed, tables and cards were stripped of pill clutter, and accepted students finally got a dignified way to release their other pending applications — each change proven with curl traces and Playwright screenshots.</p><p>A production audit with fresh eyes surfaced an uncomfortable truth: our beloved demo conveniences had leaked into user-facing flows. The E2E reset and passwordless login hooks in <code class=\'bg-cream text-ink px-1 rounded\'>login.php</code> answered to anyone who asked, and worse, the guest Apply redirect pointed at <code class=\'bg-cream text-ink px-1 rounded\'>login.php?demo=student</code> — so a visitor who clicked Apply Now on the homepage woke up signed in as Juan Dela Cruz. I gated both hooks to loopback-only plus a non-production <code class=\'bg-cream text-ink px-1 rounded\'>APP_ENV</code> with a strict student/employer/admin role whitelist, and rerouted guests to the plain login form carrying a whitelisted <code class=\'bg-cream text-ink px-1 rounded\'>next</code> return-to target (relative portal paths only — an evil.com payload was curl-tested and rejected). After a manual sign-in, students land back on the exact requisition they wanted.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-palette-fill text-accent me-2\'></i>Paper Discipline: Pills, Emojis & Phantom Domains</h5><p>The shared <code class=\'bg-cream text-ink px-1 rounded\'>render_page_head()</code> helper defaulted every page title to a green badge pill, in direct violation of our own badges-for-data-only law — it now emits a plain-text kicker, and the homepage and forgot-password pills followed it into eyebrow text. All eight category preset emojis (duplicated across both admin modals) became proper Bootstrap icons, all twelve Campus AI reply templates were de-emojied with the JSON API contract returned to plain text, and six stray <code class=\'bg-cream text-ink px-1 rounded\'>campus-hire.edu</code> contacts were unified to the real <code class=\'bg-cream text-ink px-1 rounded\'>kld.edu.ph</code> domain. The CAMPUS FAQ badge and its siblings (AI Companion, Student Career Copilot) were purged from both fullscreen chatbot modals and the speech bubble, the redundant green dark-mode switch in Settings was deleted in favor of the segmented control, and the duplicate Back to Vacancies button on job details was removed.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-table text-accent me-2\'></i>Tables: One Box, One Dot</h5><p>The analytics table swapped pill classes per cell value, so IN PROGRESS rendered visibly larger than Open Quota and a 1/5 fill count looked nothing like its 0/6 neighbors. The new <code class=\'bg-cream text-ink px-1 rounded\'>.cell-flag</code> system gives every state one identical 28px box — ink text, hairline border — with meaning carried only by a 7px status dot (filled, in-progress, over-quota, open), all tokens carrying dark-mode values. Fill counts are now permanently neutral chips since the ratio bar and the flag already tell the story, the decorative Term pill became plain text, and the job-card photo dropped from four overlay pills to a single Featured ribbon with employer type, category, and pay relocated to a clean body metadata row.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-check-circle-fill text-accent me-2\'></i>Accepted-Student Flow: Prompt, Never Force</h5><p>No auto-withdraw existed — accepting a student only bumped slot counters and sent a notification. I deliberately chose prompt-to-withdraw over silent auto-withdraw: students may legitimately stack OJT with part-time work, and silent deletes invite RA 10173 disputes and confused supervisors. A CSRF-guarded <code class=\'bg-cream text-ink px-1 rounded\'>withdraw_others</code> handler (pending-only, ownership-checked, confirm-guarded) powers a congratulations banner that persists across logins until the record is clean. I staged a demo Juan with one acceptance and two pending applications, captured the screenshots, then deleted the demo rows and reverted — with the database verified byte-identical to its prior state.</p>\",\"key_takeaways\":[\"Gated ?reset/?demo hooks to loopback + non-production with role whitelisting, and fixed a guest Apply redirect that auto-logged visitors in as another student.\",\"Shipped a whitelisted next return-to flow so guests land back on their exact requisition after a manual sign-in, with open redirects curl-tested shut.\",\"Replaced per-value table pills with a uniform .cell-flag dot system and cut job-card photos to a single Featured overlay.\",\"Built an opt-in withdraw-others flow for accepted students with CSRF + ownership guards, proven via Playwright screenshots with full demo-data cleanup.\"],\"tech_stack\":[\"Loopback-Gated Test Hooks\",\"Open-Redirect Whitelisting\",\"CSS Status Tokens\",\"Paper Dot Flags\",\"CSRF-Guarded Mutations\",\"Playwright E2E Screenshots\"]}', '2026-09-11 10:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-13', '13', 'Dual-Persona Developer Photography, Cyber Glitch & RGB Split Transitions, Unified Chatbot Modal & Global Dark Overrides', 'September 10, 2026', 'Engineered dynamic dual-persona developer photography with light/dark portraits across all team touchpoints, crafted a 300ms hardware-accelerated Cyber Glitch & RGB Split transition with Hover Peek preview, unified the FAQ Chatbot with the index 3D robot companion modal, and resolved global dark mode contrast anomalies.', '{\"id\":\"day-13\",\"sprint_number\":\"13\",\"sprint_badge\":\"DAY 13 · DUAL PERSONAS & CYBER GLITCH ENGINE\",\"title\":\"Dual-Persona Developer Photography, Cyber Glitch & RGB Split Transitions, Unified Chatbot Modal & Global Dark Overrides\",\"date\":\"September 10, 2026\",\"read_time\":\"7 min read\",\"author_name\":\"Alwinson Bustamante\",\"author_role\":\"Lead Developer & System Architect\",\"author_image\":\"assets/img/developers/BUSTAMANTE.jpg\",\"summary_excerpt\":\"Engineered dynamic dual-persona developer photography with light/dark portraits across all team touchpoints, crafted a 300ms hardware-accelerated Cyber Glitch & RGB Split transition with Hover Peek preview, unified the FAQ Chatbot with the index 3D robot companion modal, and resolved global dark mode contrast anomalies.\",\"tags\":[\"Dual-Persona Photos\",\"Cyber Glitch Transition\",\"RGB Split FX\",\"Hover Peek\",\"Unified Chatbot Modal\",\"Dark Mode Polish\"],\"cover_image\":\"assets/img/devblog/day-13.jpg\",\"full_story\":\"<p class=\\\'lead text-ink fw-semibold\\\'>Today brought our system\\\'s visual identity, responsiveness, and interactive polish to an unprecedented level. We engineered dynamic dual-persona developer photography with custom Cyber Glitch and RGB Split transitions, unified our Campus AI assistant modal across pages, and resolved complex dark mode contrast edge cases.</p><p>As part of our mission to deliver a world-class institutional experience, our team needed to embody the dual character of our platform: clean, crisp institutional day-to-day operations in daytime mode, and high-performance engineering focus in dark mode. We introduced formal dual-persona 2x2 institutional portraits for all six developers—featuring daytime institutional attire and sleek dark mode photography across the About Us team grid, the DevBlog coverflow, and the floating landing page circles.</p><h5 class=\\\'fw-bold text-ink mt-4 mb-2\\\'><i class=\\\'bi bi-lightning-charge-fill text-accent me-2\\\'></i>Cyber Glitch & RGB Split Transition Engine</h5><p>Rather than settling for a standard opacity fade when toggling themes, I designed and coded a custom, hardware-accelerated <strong>Cyber Glitch & RGB Split Transition</strong>. Built using CSS3 <code>drop-shadow</code> chromatic aberration (splitting into cyan <code>#00F0FF</code> and neon crimson <code>#FF1E56</code> channels), horizontal slice jitter (<code>skewX</code> and subpixel displacements), and an animated scanline sweep, the 320ms transition delivers a tactile, sci-fi cyberpunk feel without any audio intrusion or performance hitching.</p><p>To eliminate any perceptual latency or white flicker during rapid toggling, the engine runs an asset preloading cycle on DOM ready, caching both light and dark portraits in browser memory. The image source swap executes at the exact 140ms midpoint peak of maximum jitter distortion, ensuring a seamless visual transformation. Furthermore, I engineered an interactive <strong>Hover Peek</strong> capability: hovering over any developer card or floating bubble triggers a micro-glitch preview revealing the alternate persona, smoothly restoring when the cursor leaves.</p><h5 class=\\\'fw-bold text-ink mt-4 mb-2\\\'><i class=\\\'bi bi-robot text-accent me-2\\\'></i>Unified Campus AI Assistant Modal</h5><p>On <code class=\\\'bg-cream text-ink px-1 rounded\\\'>faqs.php</code>, the chatbot previously rendered as an isolated offcanvas drawer that conflicted with our paper design language. Today, I completely unified the FAQ chatbot interface with our flagship full-screen 2-column modal from the index page. Powered by our Three.js 3D GLTF robot companion and NVIDIA NIM AI Cloud Gateway, the unified assistant modal delivers full multi-turn conversational intelligence, instant topic suggestions, and zero-reload responsiveness across the portal.</p><h5 class=\\\'fw-bold text-ink mt-4 mb-2\\\'><i class=\\\'bi bi-moon-stars-fill text-accent me-2\\\'></i>Dark Mode Typography & Contrast Hardening</h5><p>We audited all interface surfaces in dark mode, curing contrast regressions across badge indicators, numeric counters, form inputs, call-to-action buttons, and calendar icons. Buttons such as the index CTA now boast high-contrast dark text on bright KLD Green, and secondary buttons feature clear luminous borders and crisp icons. Our automated Playwright suite confirmed 100% test success with zero regressions across both light and dark themes!</p>\",\"key_takeaways\":[\"Engineered dual-persona developer photography with light and dark portraits across all team touchpoints.\",\"Created 300ms hardware-accelerated Cyber Glitch & RGB Split transition with instant preloading and Hover Peek preview.\",\"Unified FAQ chatbot with the index 3D robot companion modal for a seamless multi-turn AI experience.\",\"Hardened global dark mode styling, curing contrast anomalies across badges, counters, and action buttons.\"],\"tech_stack\":[\"CSS3 Chromatic Aberration\",\"Hardware-Accelerated Glitch\",\"Vanilla JS Theme Engine\",\"Dual-Persona Photography\",\"Three.js Robot Companion\",\"Playwright E2E Suite\"]}', '2026-09-10 10:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-12', '12', 'Tactile De-Pilling, 14-Pillar Tech Architecture Overhaul, Filter Consolidation & 3D Typography Sharpness', 'September 09, 2026', 'Enforced strict paper aesthetic guidelines by eliminating decorative pill clutter across About Us and DevBlog, overhauled Technical Architecture to showcase our authentic 14-pillar stack (Three.js WebGL & GLTF robot, MySQL/MariaDB PDO, NVIDIA NIM AI), unified redundant reset controls, and eradicated 3D perspective blur for crystal-sharp typography.', '{\"id\":\"day-12\",\"sprint_number\":\"12\",\"sprint_badge\":\"DAY 12 · DE-PILLING, ARCHITECTURE & GPU RENDERING\",\"title\":\"Tactile De-Pilling, 14-Pillar Tech Architecture Overhaul, Filter Consolidation & 3D Typography Sharpness\",\"date\":\"September 09, 2026\",\"read_time\":\"7 min read\",\"author_name\":\"Alwinson Bustamante\",\"author_role\":\"Lead Developer & System Architect\",\"author_image\":\"assets/img/developers/BUSTAMANTE.jpg\",\"summary_excerpt\":\"Enforced strict paper aesthetic guidelines by eliminating decorative pill clutter across About Us and DevBlog, overhauled Technical Architecture to showcase our authentic 14-pillar stack (Three.js WebGL & GLTF robot, MySQL/MariaDB PDO, NVIDIA NIM AI), unified redundant reset controls, and eradicated 3D perspective blur for crystal-sharp typography.\",\"tags\":[\"Tactile Paper UI\",\"Three.js & GLTF\",\"14-Pillar Stack\",\"Filter Consolidation\",\"GPU Subpixel Sharpness\"],\"cover_image\":\"assets/img/devblog/day-12.jpg\",\"full_story\":\"<p class=\'lead text-ink fw-semibold\'>Today was a milestone in design purity, architectural transparency, and rendering precision. We eliminated decorative pill clutter, brought our technical documentation in line with our real 14-pillar engineering stack, unified student filter controls, and diagnosed and cured GPU texture magnification blur across our 3D stage.</p><p>As our project evolved, visual debt accumulated in the form of decorative rounded pill badges and stadium capsules that violated our tactile Paper Sheet aesthetic guidelines. I led a comprehensive cleanup across <code class=\'bg-cream text-ink px-1 rounded\'>about-us.php</code>, stripping away decorative eyebrow tags and transforming card badges, author date tags, developer role badges, and navigation controls into crisp, structured paper chips with subtle borders and intentional typography. In the interactive reader modal, I removed the redundant bottom close button and footer entirely, reclaiming prime reading space for engineering narratives and deliverables.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-cpu-fill text-accent me-2\'></i>Overhauling Technical Architecture: The Authentic 14 Pillars</h5><p>Our About Us page had previously displayed legacy placeholder notes referencing a flat-file JSON datastore. I completely replaced that section with an authentic <strong>14-Pillar Technical Architecture Spec Grid</strong> (<code class=\'bg-cream text-ink px-1 rounded\'>.tech-spec-grid</code>). It transparently details our full production stack: <strong>Three.js WebGL & GLTFLoader</strong> driving our 3D robot mascot (<code class=\'bg-cream text-ink px-1 rounded\'>cute_robot.glb</code>) with 13 procedural kinematics and OLED visor shaders, <strong>MySQL 8.0/MariaDB (InnoDB)</strong> with ACID transactions, <strong>PHP PDO Prepared Statements</strong> with zero SQL injection vectors, atomic database migrations (<code class=\'bg-cream text-ink px-1 rounded\'>database/migrate.php</code>), Native PHP 8.2+ RBAC, NVIDIA NIM AI Gateway (<code class=\'bg-cream text-ink px-1 rounded\'>Llama-3.3-70B-Instruct</code>) with multi-turn memory, local heuristic fallbacks, modular CSS design tokens, Bootstrap 5.3, vanilla ES6+ JavaScript with Shannon entropy calculations, 30s background notification polling, Bcrypt/anti-CSRF security, and our 26-spec Playwright E2E automation suite.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-funnel-fill text-accent me-2\'></i>Student Jobs: Filter Consolidation & Category Data Integrity</h5><p>On <code class=\'bg-cream text-ink px-1 rounded\'>student/jobs.php</code>, three competing reset controls previously crowded the viewport (hero banner reset pill, category header clear link, and toolbar reset button). I consolidated these down to a single authoritative reset button in the filter toolbar and replaced the hero pill with an informative Active Discipline badge. Concurrently, I tracked down an insidious category count bug in <code class=\'bg-cream text-ink px-1 rounded\'>includes/data-helper.php</code> where categories without active jobs retained static seed numbers; I fixed the aggregation fallback and seeded the missing Sports & Athletics Aide jobs (#9 and #10) so the live catalog perfectly matches database records.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-eye-fill text-accent me-2\'></i>Diagnosing & Eradicating 3D GPU Perspective Blur</h5><p>When inspecting our 3D Coverflow DevBlog, we noticed a subtle rendering flaw: text on the front active card appeared fuzzy and blurry, while cards in the back remained sharp. Profiling Chromium\'s rendering pipeline revealed that <code class=\'bg-cream text-ink px-1 rounded\'>translateZ(80px)</code> under <code class=\'bg-cream text-ink px-1 rounded\'>perspective: 1400px</code> projected the front card 6% closer to the camera, forcing the GPU to stretch the 1x offscreen bitmap texture bilinearly instead of re-rasterizing vector glyphs. Meanwhile, back cards were scaled down (<code class=\'bg-cream text-ink px-1 rounded\'>scale(0.86)</code>), downsampling pixels crisply. Furthermore, <code class=\'bg-cream text-ink px-1 rounded\'>transform-style: preserve-3d</code> ignored DOM z-index, causing rotated side cards to slice through flat elements. I eliminated <code class=\'bg-cream text-ink px-1 rounded\'>translateZ(80px)</code>, switched the track to <code class=\'bg-cream text-ink px-1 rounded\'>transform-style: flat</code>, and applied individual perspective to flanking cards. The active card now renders at exact 1:1 pixel scale with razor-sharp subpixel ClearType antialiasing and flawless z-index stacking!</p>\",'key_takeaways':[\"Enforced tactile paper design guidelines by de-pilling About Us and DevBlog, removing duplicate modal footer.\",\"Overhauled Technical Architecture to showcase authentic 14-pillar stack featuring Three.js, MySQL PDO, and NVIDIA NIM.\",\"Consolidated 3 redundant filter reset controls on student jobs and resolved category count aggregation bug.\",\"Eliminated 3D GPU perspective texture magnification blur, restoring razor-sharp 1:1 subpixel typography on the active card.\"],\"tech_stack\":[\"Three.js WebGL\",\"MySQL InnoDB\",\"CSS 3D Projection Optimization\",\"Subpixel Typography\",\"UI/UX Paper Tokens\",\"Playwright E2E\"]}', '2026-09-09 20:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-11', '11', 'Modular CSS Architecture, Role-Based Navbar, Multi-Turn AI Memory & 20-Hour Academic Labor Cap', 'September 08, 2026', 'Refactored monolithic CSS into 7 scoped architectural modules, engineered dynamic role-based navbar routing with a centered Google-style spotlight search, added multi-turn conversational memory to Campus AI, and strictly capped weekly student assistant hours to 20h.', '{"id":"day-11","sprint_number":"11","sprint_badge":"DAY 11 · MODULAR CSS & 20H POLICY SAFEGUARDS","title":"Modular CSS Architecture, Role-Based Navbar, Multi-Turn AI Memory & 20-Hour Academic Labor Cap","date":"September 08, 2026","read_time":"6 min read","author_name":"Alwinson Bustamante","author_role":"Lead Developer & System Architect","author_image":"assets/img/developers/BUSTAMANTE.jpg","summary_excerpt":"Refactored monolithic CSS into 7 scoped architectural modules, engineered dynamic role-based navbar routing with a centered Google-style spotlight search, added multi-turn conversational memory to Campus AI, and strictly capped weekly student assistant hours to 20h.","tags":["Modular CSS","Role Navbar","Multi-Turn AI","20-Hour Policy","Mobile UX"],"cover_image":"assets/img/devblog/day-11.jpg","full_story":"<p class=\'lead text-ink fw-semibold\'>With our final presentation and system evaluation on the horizon, today was dedicated to high-level structural refactoring, navigational fluidity, and strict institutional policy enforcement.</p><p>As systems grow in complexity, stylesheet maintenance can quickly degrade without strict discipline. I tackled this head-on today by breaking apart our monolithic <code class=\'bg-cream text-ink px-1 rounded\'>custom.css</code> into 7 domain-specific modules: <code class=\'bg-cream text-ink px-1 rounded\'>variables.css</code>, <code class=\'bg-cream text-ink px-1 rounded\'>base.css</code>, <code class=\'bg-cream text-ink px-1 rounded\'>components.css</code>, <code class=\'bg-cream text-ink px-1 rounded\'>layout.css</code>, <code class=\'bg-cream text-ink px-1 rounded\'>auth.css</code>, <code class=\'bg-cream text-ink px-1 rounded\'>dashboard.css</code>, and <code class=\'bg-cream text-ink px-1 rounded\'>robot.css</code>. To optimize asset delivery, I replaced timestamp query cache-busting with <code class=\'bg-cream text-ink px-1 rounded\'>filemtime()</code> in <code class=\'bg-cream text-ink px-1 rounded\'>includes/header.php</code>, ensuring optimal client caching while guaranteeing real-time updates when files are edited.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-grid-fill text-accent me-2\'></i>3-Column Role Navbar & Centered Spotlight Search</h5><p>I completely restructured <code class=\'bg-cream text-ink px-1 rounded\'>navbar.php</code> using a clean 3-column CSS Grid. The campus brand logo now routes dynamically based on session role—sending students directly to <code class=\'bg-cream text-ink px-1 rounded\'>student/dashboard.php</code>, employers to their requisitions, and admins to analytical reports. For authenticated users, I introduced an elegant centered Google-style search bar that triggers our debounced universal spotlight search modal (<code class=\'bg-cream text-ink px-1 rounded\'>Ctrl+K</code>) without layout jitter or horizontal collisions.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-chat-left-dots-fill text-accent me-2\'></i>Campus AI Multi-Turn Memory & Navigation Intelligence</h5><p>I upgraded our Campus AI companion gateway by feeding the entire portal sitemap and session role context into the system prompt. Conversations now retain a sliding multi-turn conversational memory across <code class=\'bg-cream text-ink px-1 rounded\'>faqs.php</code> and the hero assistant, with plural-aware regex for our curated local offline fallback engine.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-clock-history text-accent me-2\'></i>Institutional 20-Hour Labor Cap & Mobile Filters</h5><p>To strictly adhere to the university standard safeguarding student academic standing, I implemented client and server-side validation capping weekly student assistant shifts to a hard maximum of <strong>20 hours per week</strong> across job requisition creation and editing forms. Furthermore, I redesigned the shared footer into an unsegmented modern unit and transformed the mobile job search filters into a smooth collapsible accordion with live filter count badges.</p>","key_takeaways":["Modularized monolithic CSS into 7 scoped stylesheets and integrated filemtime() asset caching.","Engineered 3-column CSS Grid navbar with dynamic role-based logo routing and centered spotlight search.","Implemented multi-turn conversational memory and sitemap navigation in Campus AI companion.","Strictly enforced statutory 20-hour/week student labor cap with server-side validation."],"tech_stack":["Modular CSS Architecture","CSS Grid 3-Column Navbar","Multi-Turn AI Memory","Policy Validation","filemtime Caching"]}', '2026-09-08 12:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-10', '10', 'Building the Multi-Role Notification Engine: Real-Time Polling, Verification Triggers & Migration Whitelists', 'September 07, 2026', 'Architected an asynchronous multi-role notification pipeline with 30-second background polling, lifecycle verification triggers across student applications and employer accreditations, and hardened database migration loops with strict table whitelisting.', '{"id":"day-10","sprint_number":"10","sprint_badge":"DAY 10 · REAL-TIME NOTIFICATIONS & ENGINE SECURITY","title":"Building the Multi-Role Notification Engine: Real-Time Polling, Verification Triggers & Migration Whitelists","date":"September 07, 2026","read_time":"5 min read","author_name":"Alwinson Bustamante","author_role":"Lead Developer & System Architect","author_image":"assets/img/developers/BUSTAMANTE.jpg","summary_excerpt":"Architected an asynchronous multi-role notification pipeline with 30-second background polling, lifecycle verification triggers across student applications and employer accreditations, and hardened database migration loops with strict table whitelisting.","tags":["Notification System","AJAX Polling","Lifecycle Triggers","Migration Security"],"cover_image":"assets/img/devblog/day-10.jpg","full_story":"<p class=\'lead text-ink fw-semibold\'>Clear communication and instantaneous feedback are critical for our multi-role institutional platform. Today, I built an end-to-end real-time in-app notification infrastructure.</p><p>I established the relational <code class=\'bg-cream text-ink px-1 rounded\'>notifications</code> table in MySQL with foreign key constraints, indexes, and automated cascading cleanup. In <code class=\'bg-cream text-ink px-1 rounded\'>includes/data-helper.php</code>, I implemented dynamic lifecycle event triggers: students receive instant updates when their application shifts state (Under Review, Interview Scheduled with date & venue, Accepted, Declined) and when profile change requests are resolved. Employers are alerted immediately upon new student submissions or when their institutional accreditation is verified, while admins receive real-time notifications for incoming registrations and student COR requests.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-bell-fill text-accent me-2\'></i>Navbar Dropdown, Toast Alerts & Notification Center</h5><p>I engineered <code class=\'bg-cream text-ink px-1 rounded\'>api/notifications.php</code> and <code class=\'bg-cream text-ink px-1 rounded\'>assets/js/notifications.js</code> to handle 30-second background polling with <code class=\'bg-cream text-ink px-1 rounded\'>document.visibilitychange</code> lifecycle pausing to preserve battery and network bandwidth. Unread pings display non-intrusive floating toasts and increment the navbar bell counter. Furthermore, I built a dedicated Notification Center (<code class=\'bg-cream text-ink px-1 rounded\'>notifications.php</code>) featuring chip-filtered tabs (All/Unread), \'Mark All as Read\', and direct deep-links to associated records.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-shield-check text-accent me-2\'></i>Migration Truncate Whitelist Hardening</h5><p>To eliminate any possibility of command injection or malicious table manipulation during database resets, I hardened <code class=\'bg-cream text-ink px-1 rounded\'>database/migrate.php</code> by wrapping all truncate operations in a strict table name whitelist array validated by regex prior to execution.</p>","key_takeaways":["Engineered relational notifications schema with user foreign keys and automated lifecycle triggers.","Built 30-second background polling engine with tab visibility suspension and floating toast alerts.","Developed comprehensive Notification Center (notifications.php) with unread filtering and batch actions.","Hardened database migration reset scripts with strict table whitelist and regex validation."],"tech_stack":["MySQL Foreign Keys","AJAX Background Polling","Lifecycle Event Hooks","Floating Toast UI","Regex Whitelisting"]}', '2026-09-08 12:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-09', '09', 'Integrating NVIDIA NIM AI Campus Studio: 2-Column Interface, Domain Photography & Zero-Reload Filtering', 'September 06, 2026', 'Integrated an enterprise NVIDIA NIM AI gateway with a fullscreen 2-column studio, dynamic intent detection, high-resolution domain photography across job families, and zero-reload AJAX category filtering with scroll preservation.', '{"id":"day-09","sprint_number":"09","sprint_badge":"DAY 09 · NVIDIA NIM AI & VISUAL TAXONOMY","title":"Integrating NVIDIA NIM AI Campus Studio: 2-Column Interface, Domain Photography & Zero-Reload Filtering","date":"September 06, 2026","read_time":"7 min read","author_name":"Alwinson Bustamante","author_role":"Lead Developer & System Architect","author_image":"assets/img/developers/BUSTAMANTE.jpg","summary_excerpt":"Integrated an enterprise NVIDIA NIM AI gateway with a fullscreen 2-column studio, dynamic intent detection, high-resolution domain photography across job families, and zero-reload AJAX category filtering with scroll preservation.","tags":["NVIDIA NIM AI","Fullscreen Studio","Domain Photography","Zero-Reload AJAX"],"cover_image":"assets/img/devblog/day-09.jpg","full_story":"<p class=\'lead text-ink fw-semibold\'>Today we bridged artificial intelligence with high-fidelity visual design, turning our platform into a cutting-edge, visually rich student career portal.</p><p>I developed our enterprise AI Assistant integration using NVIDIA NIM (<code class=\'bg-cream text-ink px-1 rounded\'>Llama-3.3-70B-Instruct</code>), backed by secure server-side dispatching in <code class=\'bg-cream text-ink px-1 rounded\'>api/robot-chat.php</code> and <code class=\'bg-cream text-ink px-1 rounded\'>includes/ai-config.php</code>. I implemented campus intent classification (career guidance, resume writing, interview prep, policy queries) and built an immersive <strong>Fullscreen 2-Column Studio</strong> that pairs our live 3D mascot on the left with a real-time markdown chat stream console on the right.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-images text-accent me-2\'></i>Domain Photography & Visual Taxonomy Showcase</h5><p>To eliminate clinical corporate monotony, I upgraded our entire category taxonomy with high-resolution photography representing campus job families (Tech Lab, Library, Science Research, Peer Tutoring, Athletic Facility, Creative Media, Administrative Office, Campus Cafe). I designed glassmorphic badge overlays for verified employers, work setups, and hourly rates, and built a rich visual category showcase banner in both <code class=\'bg-cream text-ink px-1 rounded\'>student/jobs.php</code> and <code class=\'bg-cream text-ink px-1 rounded\'>admin/categories.php</code>.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-arrow-repeat text-accent me-2\'></i>Zero-Reload AJAX Filtering & FAQ Bot</h5><p>I upgraded job browsing so students can filter by job families without jarring full-page reloads. Using vanilla JS fetch and <code class=\'bg-cream text-ink px-1 rounded\'>history.pushState()</code>, the DOM updates asynchronously while completely preserving scroll position. Finally, I integrated the Campus AI assistant directly into the FAQ page (<code class=\'bg-cream text-ink px-1 rounded\'>faqs.php</code>) to answer unlisted student questions on demand.</p>","key_takeaways":["Integrated NVIDIA NIM AI gateway with intent classification, rate limiting, and local curated fallbacks.","Constructed immersive 2-column fullscreen studio uniting 3D WebGL mascot with streaming markdown chat.","Overhauled job cards and category taxonomy with domain photography and glassmorphic metadata chips.","Engineered zero-reload AJAX category filtering with HTML5 pushState history and scroll preservation."],"tech_stack":["NVIDIA NIM API","Fullscreen Studio Layout","Vanilla JS Fetch API","HTML5 History API","Glassmorphism Tokens"]}', '2026-09-08 12:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-08', '08', 'Giving Life to the Mascot: 13 Kinetic Animations, Typewriter Speech Bubble & Interactive Dialogue Modes', 'September 05, 2026', 'Elevated the 3D robot mascot with 13 expressive procedural animations, synchronized head and visor micro-motions, an interactive typewriter speech bubble, and dynamic dialogue modes (/boost, /grill-me, and Talk).', '{"id":"day-08","sprint_number":"08","sprint_badge":"DAY 08 · ROBOT KINEMATICS & EXPRESSIONS","title":"Giving Life to the Mascot: 13 Kinetic Animations, Typewriter Speech Bubble & Interactive Dialogue Modes","date":"September 05, 2026","read_time":"5 min read","author_name":"Alwinson Bustamante","author_role":"Lead Developer & System Architect","author_image":"assets/img/developers/BUSTAMANTE.jpg","summary_excerpt":"Elevated the 3D robot mascot with 13 expressive procedural animations, synchronized head and visor micro-motions, an interactive typewriter speech bubble, and dynamic dialogue modes (/boost, /grill-me, and Talk).","tags":["Three.js Kinematics","3D Mascot","Procedural Motion","OLED Eye Shaders"],"cover_image":"assets/img/devblog/day-08.jpg","full_story":"<p class=\'lead text-ink fw-semibold\'>Having established the 3D WebGL canvas yesterday, today\'s mission was giving our robot companion true personality, charisma, and emotional depth.</p><p>I replaced basic jumping bounces with an arsenal of <strong>13 distinct procedural animations</strong> in <code class=\'bg-cream text-ink px-1 rounded\'>assets/js/hero-robot.js</code>: winking, squinting scans, curious head tilts, excited nodding, 360° celebratory spins, empathetic sways, and respectful campus bows. Every movement is smoothly interpolated through spring-damped matrices to prevent mechanical abruptness.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-chat-quote-fill text-accent me-2\'></i>Interactive Speech Bubble & Typewriter Micro-Gestures</h5><p>I engineered an interactive floating speech bubble positioned directly above the companion. As dialogue renders character-by-character via a typewriter cadence, the robot\'s head and visor perform synchronized micro-bobs, giving the unmistakable impression of genuine verbal articulation.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-sliders text-accent me-2\'></i>Three Dialogue Modes & OLED Visor Color Shifts</h5><p>I programmed 3 distinct interaction modes: <strong>Talk</strong> (friendly campus advice), <strong>/boost</strong> (career confidence & academic motivation), and <strong>/grill-me</strong> (rigorous mock interview preparation). When students switch modes, the companion\'s OLED eye shader smoothly shifts colors—from KLD emerald green to alert amber and sharp cyan—providing immediate visual feedback.</p>","key_takeaways":["Programmed 13 procedural kinetic animations with spring damping and clamped kinematics.","Built dynamic typewriter speech bubble with synchronized mascot micro-gestures.","Implemented 3 interactive dialogue modes with real-time OLED emissive eye shader color transitions.","Optimized WebGL rendering loops with IntersectionObserver to conserve client device resources."],"tech_stack":["Three.js WebGL","Procedural Kinematics","Typewriter DOM Engine","Emissive Visor Shaders","IntersectionObserver"]}', '2026-09-08 12:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-07', '07', 'The 3-Step Persona Registration Wizard, Defensive Data Gating & 3D Robot Mascot Genesis', 'September 04, 2026', 'Transformed registration into an intuitive 3-step persona wizard, hardened client/server validation against double-encoding and race conditions, and integrated the 3D WebGL robot mascot with real-time cursor kinematics.', '{"id":"day-07","sprint_number":"07","sprint_badge":"DAY 07 · PERSONA WIZARD & 3D MASCOT GENESIS","title":"The 3-Step Persona Registration Wizard, Defensive Data Gating & 3D Robot Mascot Genesis","date":"September 04, 2026","read_time":"6 min read","author_name":"Alwinson Bustamante","author_role":"Lead Developer & System Architect","author_image":"assets/img/developers/BUSTAMANTE.jpg","summary_excerpt":"Transformed registration into an intuitive 3-step persona wizard, hardened client/server validation against double-encoding and race conditions, and integrated the 3D WebGL robot mascot with real-time cursor kinematics.","tags":["3-Step Wizard","Three.js WebGL","Defensive Hardening","Ocular Tracking"],"cover_image":"assets/img/devblog/day-07.jpg","full_story":"<p class=\'lead text-ink fw-semibold\'>September 04 was a high-output development day spanning user onboarding UX, defensive server-side fixes, and the birth of our 3D WebGL mascot.</p><p>I completely restructured <code class=\'bg-cream text-ink px-1 rounded\'>register.php</code> from a long, exhausting form into an intuitive <strong>3-Step Registration Wizard</strong>. I replaced cumbersome dropdowns with a 1-click 3-persona card grid (Student Applicant, University Department, Accredited Industry Partner), an active vertical step indicator, and an 8px luminous green progress bar.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-shield-shaded text-accent me-2\'></i>Relentless Defensive Hardening Marathon</h5><p>I eliminated premature <code class=\'bg-cream text-ink px-1 rounded\'>htmlspecialchars()</code> entity escaping across candidate evaluation notes, student cover letters, and category names, storing raw data cleanly in MySQL and preventing double-encoding (<code class=\'bg-cream text-ink px-1 rounded\'>&amp;amp;</code>). I attached double-submission button locking with spinners across all POST forms and upgraded the student application tracker with structured status callouts and dual digital/printable CV action buttons.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-robot text-accent me-2\'></i>Interactive 3D WebGL Mascot Genesis</h5><p>To give our institution a modern, friendly identity, I integrated Three.js and loaded <code class=\'bg-cream text-ink px-1 rounded\'>cute_robot.glb</code> into our landing hero. I isolated the primary mascot mesh, styled materials in KLD deep forest green and glowing emerald visor emission (<code class=\'bg-cream text-ink px-1 rounded\'>#22c55e</code>), and implemented real-time cursor tracking with clamped kinematics (0.058 lerp) and dual-layer ocular visor tracking (0.10 lerp).</p>","key_takeaways":["Converted registration into a 3-step wizard with persona cards and sticky input validation.","Eliminated HTML entity double-escaping and implemented double-submit locking across all forms.","Enhanced student application tracker with structured status callouts and printable CV actions.","Integrated interactive 3D WebGL robot mascot with real-time cursor tracking and ocular visor physics."],"tech_stack":["Three.js GLTFLoader","Lerp Kinematics","Bootstrap 5 Stepper","Input Normalization","WebGL Power Optimization"]}', '2026-09-08 12:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-06', '06', 'Relational Foreign Keys, Swarm Security Hardening & Permanent Demo/Real Data Coexistence', 'September 03, 2026', 'Implemented explicit MySQL foreign key constraints with EER semantic labels, conducted a comprehensive swarm security audit hardening MIME types and IDOR boundaries, and unified demo/real datastores for permanent coexistence.', '{"id":"day-06","sprint_number":"06","sprint_badge":"DAY 06 · RELATIONAL INTEGRITY & DEFENSE-IN-DEPTH","title":"Relational Foreign Keys, Swarm Security Hardening & Permanent Demo/Real Data Coexistence","date":"September 03, 2026","read_time":"6 min read","author_name":"Alwinson Bustamante","author_role":"Lead Developer & System Architect","author_image":"assets/img/developers/BUSTAMANTE.jpg","summary_excerpt":"Implemented explicit MySQL foreign key constraints with EER semantic labels, conducted a comprehensive swarm security audit hardening MIME types and IDOR boundaries, and unified demo/real datastores for permanent coexistence.","tags":["Relational Integrity","Foreign Keys","Swarm Security Audit","IDOR Protection"],"cover_image":"assets/img/devblog/day-06.jpg","full_story":"<p class=\'lead text-ink fw-semibold\'>With MySQL fully active, today was dedicated to relational modeling rigor, database constraint enforcement, and ironclad defense-in-depth security.</p><p>I enhanced <code class=\'bg-cream text-ink px-1 rounded\'>database/schema.sql</code> with explicit semantic foreign key constraints (<code class=\'bg-cream text-ink px-1 rounded\'>fk_jobs_category</code>, <code class=\'bg-cream text-ink px-1 rounded\'>fk_jobs_employer</code>, <code class=\'bg-cream text-ink px-1 rounded\'>fk_apps_job</code>, <code class=\'bg-cream text-ink px-1 rounded\'>fk_apps_student</code>) and added <code class=\'bg-cream text-ink px-1 rounded\'>UNIQUE KEY unique_student_job</code> to prevent duplicate submissions at the relational level.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-shield-lock text-accent me-2\'></i>Swarm Security Audit & Defensive Hardening</h5><p>I executed a comprehensive security audit across all entry points: whitelisted registration roles strictly to <code class=\'bg-cream text-ink px-1 rounded\'>[\'student\', \'employer\']</code> preventing privilege escalation to admin; upgraded authentication to native <code class=\'bg-cream text-ink px-1 rounded\'>password_hash()</code> and scrubbed hashes from session superglobals; implemented strict <code class=\'bg-cream text-ink px-1 rounded\'>finfo_file</code> MIME inspection on all document uploads; and scoped employer review endpoints strictly to primary-key ownership (<code class=\'bg-cream text-ink px-1 rounded\'>employer_id === user[\'id\']</code>) to eradicate IDOR vulnerabilities.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-database-check text-accent me-2\'></i>Demo & Real Data Coexistence</h5><p>I removed artificial dataset switching and destructive table wipes. Demo benchmark listings and live registered student/employer accounts now coexist permanently in MySQL, with live admin COR/ID verification inspection modals in <code class=\'bg-cream text-ink px-1 rounded\'>admin/users.php</code> that sync immediately to active sessions.</p>","key_takeaways":["Defined explicit relational foreign key constraints and UNIQUE (job_id, student_id) indexes.","Hardened authentication, file upload MIME validation, anti-CSRF tokens, and security headers.","Enforced strict IDOR primary-key ownership checks across employer review endpoints.","Enabled permanent coexistence of demo fixtures and real registered user records."],"tech_stack":["MySQL InnoDB Constraints","Bcrypt Hashing","MIME Validation (finfo)","Anti-CSRF Tokens","Defensive HTTP Headers"]}', '2026-09-08 12:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-05', '05', 'Enterprise MySQL Migration: Relational Schema, ACID Migrations & Full-Width 100vh Hero Viewport', 'September 02, 2026', 'Migrated the entire data persistence architecture from flat-file JSON to MySQL (PDO) with ACID migrations, expanded the viewport to 100% full-width with a 100vh landing hero, and verified all 106 Playwright tests.', '{"id":"day-05","sprint_number":"05","sprint_badge":"DAY 05 · ENTERPRISE MYSQL & 100VH HERO","title":"Enterprise MySQL Migration: Relational Schema, ACID Migrations & Full-Width 100vh Hero Viewport","date":"September 02, 2026","read_time":"6 min read","author_name":"Alwinson Bustamante","author_role":"Lead Developer & System Architect","author_image":"assets/img/developers/BUSTAMANTE.jpg","summary_excerpt":"Migrated the entire data persistence architecture from flat-file JSON to MySQL (PDO) with ACID migrations, expanded the viewport to 100% full-width with a 100vh landing hero, and verified all 106 Playwright tests.","tags":["MySQL Migration","PDO Prepared Statements","ACID Transactions","100vh Viewport"],"cover_image":"assets/img/devblog/day-05.jpg","full_story":"<p class=\'lead text-ink fw-semibold\'>Flat-file JSON persistence carried our prototype through early milestones, but enterprise scalability and concurrent applicant handling demanded a true relational database.</p><p>Today marked our largest architectural leap: migrating the data layer to <strong>MySQL/MariaDB via PHP Data Objects (PDO)</strong>. I established <code class=\'bg-cream text-ink px-1 rounded\'>includes/db.php</code> as a secure PDO connection singleton and performed a complete rewrite of <code class=\'bg-cream text-ink px-1 rounded\'>includes/data-helper.php</code>. Every read, write, filter, and state transition now executes via parameterized SQL queries, completely eliminating SQL injection risks and multi-process file concurrency race conditions.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-arrow-repeat text-accent me-2\'></i>ACID Database Migration & Seeding Engine</h5><p>I built <code class=\'bg-cream text-ink px-1 rounded\'>database/schema.sql</code> and <code class=\'bg-cream text-ink px-1 rounded\'>database/migrate.php</code>, creating an automated CLI and browser migration runner. The engine wraps schema initialization, table truncations, and JSON seed data re-import into a single atomic ACID transaction, enabling instantaneous database resets without schema corruption.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-aspect-ratio text-accent me-2\'></i>100vh Hero Section & Full-Width Paper Sheet</h5><p>I expanded the portal canvas by removing artificial max-width constraints on <code class=\'bg-cream text-ink px-1 rounded\'>.sheet</code> for a 100% full-width layout. I constructed an expansive 100vh full-screen landing hero section with vertically centered typography, elevated partner strips, and split student registration name fields (First, Middle, Last). Ran our entire automated Playwright test suite—achieving 106/106 passed tests with zero regressions!</p>","key_takeaways":["Replaced flat-file JSON storage with enterprise MySQL (PDO) prepared statements across all queries.","Engineered transactional CLI/web database migration engine (database/migrate.php).","Expanded portal layout to full-width with an immersive 100vh hero viewport and split name fields.","Achieved 100% pass rate across 106 automated Playwright E2E test specs on the new relational engine."],"tech_stack":["PHP Data Objects (PDO)","MySQL 8 / MariaDB","ACID Migration Engine","100vh Full-Width Layout","Playwright E2E Suite"]}', '2026-09-08 12:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-04', '04', 'Perfecting the Tactile Paper Sheet UX: Spotlight Search, 3D DevBlog & Final Polish', 'August 29, 2026', 'Following up on yesterday\'s UX critique, elevated the portal experience—crafting the signature Tactile Paper Sheet design system, keyboard-driven spotlight search (Ctrl+K), and interactive 3D DevBlog Coverflow.', '{"id":"day-04","sprint_number":"04","sprint_badge":"DAY 04 · TACTILE UX & SYSTEM HARMONY","title":"Perfecting the Tactile Paper Sheet UX: Spotlight Search, 3D DevBlog & Final Polish","date":"August 29, 2026","read_time":"5 min read","author_name":"Alwinson Bustamante","author_role":"Lead Developer & System Architect","author_image":"assets/img/developers/BUSTAMANTE.jpg","summary_excerpt":"Following up on yesterday\'s UX critique, elevated the portal experience—crafting the signature Tactile Paper Sheet design system, keyboard-driven spotlight search (Ctrl+K), and interactive 3D DevBlog Coverflow.","tags":["Tactile UX","Spotlight Search","Design System","Final Polish"],"cover_image":"assets/img/devblog/day-04.jpg","full_story":"<p class=\'lead text-ink fw-semibold\'>Following up on yesterday\'s self-critique where the UX still felt incomplete, today\'s objective was relentless visual and interactive perfection.</p><p>I dedicated today to turning raw functional components into a unified, tactile experience. We established the <strong>Tactile Paper Sheet Design System</strong>, introducing warm ivory canvas tones (<code class=\'bg-cream text-ink px-1 rounded\'>#FBF9F4</code>), deep carbon ink contrast (<code class=\'bg-cream text-ink px-1 rounded\'>#161616</code>), physical paper border elevations, and official KLD Green accents across all student, employer, and administrative views.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-search text-accent me-2\'></i>Universal Spotlight Search & 3D Stage DevBlog</h5><p>To make navigation effortless, I engineered the keyboard-driven universal Spotlight Search modal (<code class=\'bg-cream text-ink px-1 rounded\'>Ctrl+K</code>) that queries <code class=\'bg-cream text-ink px-1 rounded\'>api/search-jobs.php</code> with live debouncing. Furthermore, I built this interactive 3D Coverflow DevBlog on the About Us page so our entire daily journey is recorded transparently for our professor and peers.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-check-all text-accent me-2\'></i>Presentation Readiness</h5><p>With both design variations prepared and our core workflows rigorously validated across mobile and desktop devices, we are fully prepared to present our dual-design project to our professor with utmost confidence.</p>","key_takeaways":["Perfected the Tactile Paper Sheet design tokens across all student, employer, and admin interfaces.","Engineered universal Spotlight Search (Ctrl+K) with live API debounce.","Constructed the interactive 3D perspective DevBlog Coverflow and modal reader.","Ensured both design variations are polished and presentation-ready for our professor."],"tech_stack":["CSS3 3D Perspective","Spotlight Search API","Tactile Paper Tokens","Vanilla JS ES6"]}', '2026-09-08 12:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-03', '03', 'Team Git Collaboration, Mentoring Groupmates & The Dual-Design Strategy', 'August 28, 2026', 'Balanced multi-subject coursework with core development, mentored groupmates on Git and GitHub collaborative workflows, and initiated a dual-design strategy to present two strong prototypes to our professor.', '{"id":"day-03","sprint_number":"03","sprint_badge":"DAY 03 · GIT ONBOARDING & DUAL DESIGN","title":"Team Git Collaboration, Mentoring Groupmates & The Dual-Design Strategy","date":"August 28, 2026","read_time":"6 min read","author_name":"Alwinson Bustamante","author_role":"Lead Developer & System Architect","author_image":"assets/img/developers/BUSTAMANTE.jpg","summary_excerpt":"Balanced multi-subject coursework with core development, mentored groupmates on Git and GitHub collaborative workflows, and initiated a dual-design strategy to present two strong prototypes to our professor.","tags":["Git Collaboration","Team Mentoring","Dual Design","UX Critique"],"cover_image":"assets/img/devblog/day-03.jpg","full_story":"<p class=\'lead text-ink fw-semibold\'>When I woke up in the morning, well what do you expect—I quickly finished my required tasks for other subjects and immediately dove straight back into system development.</p><p>Today marked a major team milestone: I conducted a hands-on mentoring session for my groupmates to teach them how the system works, how our file hierarchy is organized, and how to use <strong>Git and GitHub for collaborative development</strong>. They learned remarkably fast and were eager to contribute.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-diagram-3-fill text-accent me-2\'></i>Dual-Design Presentation Strategy</h5><p>To maximize our impact during the midterm presentation, we planned a dual-design strategy: my groupmates would develop their design variation, while I developed mine. This ensures we can present 2 distinct, fully functioning design directions to our professor.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-clock-history text-accent me-2\'></i>The 11:30 PM Build & UX Reflections</h5><p>I completed that day\'s development build at 11:30 PM. However, stepping back to evaluate it, my design still felt incomplete and the UX did not fully satisfy my standards. I resolved then and there to start developing further tomorrow to bring the user experience to perfection.</p>","key_takeaways":["Taught groupmates Git version control and GitHub collaborative repository workflows.","Established the dual-design strategy to develop and present 2 unique prototype options.","Completed the 11:30 PM core build milestone covering applicant review and admin controls.","Critiqued UX shortcomings and established high-fidelity refinement goals for the next day."],"tech_stack":["Git & GitHub Workflows","Collaborative Branching","Bootstrap 5.3 Modals","PHP State Handlers"]}', '2026-09-08 12:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-02', '02', 'The Start of the Madness: All-Day Coding Sprint & 1:00 AM Optimization Marathon', 'August 27, 2026', 'Pushed through an intensive full-day coding marathon from early morning to 1:00 AM—building the zero-DB JSON persistence engine, session state synchronization, password entropy meter, and end-to-end application workflows.', '{"id":"day-02","sprint_number":"02","sprint_badge":"DAY 02 · DEEP DIVE & CODING MARATHON","title":"The Start of the Madness: All-Day Coding Sprint & 1:00 AM Optimization Marathon","date":"August 27, 2026","read_time":"6 min read","author_name":"Alwinson Bustamante","author_role":"Lead Developer & System Architect","author_image":"assets/img/developers/BUSTAMANTE.jpg","summary_excerpt":"Pushed through an intensive full-day coding marathon from early morning to 1:00 AM—building the zero-DB JSON persistence engine, session state synchronization, password entropy meter, and end-to-end application workflows.","tags":["Coding Marathon","JSON Engine","Session Sync","Password Entropy"],"cover_image":"assets/img/devblog/day-02.jpg","full_story":"<p class=\'lead text-ink fw-semibold\'>August 27 was the true start of creating this madness. The moment I woke up in the morning, I jumped directly into the codebase to develop and optimize the core architecture even further.</p><p>For the entire day, I worked non-stop on our zero-database data architecture. I built <code class=\'bg-cream text-ink px-1 rounded\'>includes/data-helper.php</code>, establishing atomic file reads/writes for our JSON datasets and synchronizing live states into <code class=\'bg-cream text-ink px-1 rounded\'>$_SESSION</code> for zero database overhead and lightning-fast responses.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-shield-lock-fill text-accent me-2\'></i>Security Algorithms & Shift Availability Matrix</h5><p>I engineered the standalone client-side Shannon password entropy analyzer (<code class=\'bg-cream text-ink px-1 rounded\'>password-strength.js</code>) with real-time criteria checkmarks, role-based access control (RBAC), and built the interactive 18-slot weekly schedule availability time grid matrix for student job submissions.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-moon-stars-fill text-accent me-2\'></i>Pushing Through to 1:00 AM</h5><p>I coded and optimized straight through the evening and night, finally stopping at 1:00 AM on August 28, hoping that this intensive development foundation would be solid and comprehensive enough for our project.</p>","key_takeaways":["Engineered zero-database atomic JSON persistence and dynamic session synchronization.","Implemented real-time client-side password entropy scoring and visual strength feedback.","Built the 18-slot weekly schedule availability grid matrix for student applications.","Completed a grueling 16+ hour coding marathon ending at 1:00 AM for core engine stability."],"tech_stack":["Native PHP 8","Atomic JSON Engine","Shannon Entropy Algorithm","Session Persistence"]}', '2026-09-08 12:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
INSERT INTO `devblogs` (`id`, `sprint_number`, `sprint_title`, `sprint_dates`, `sprint_focus`, `daily_logs`, `created_at`) VALUES ('day-01', '01', 'Genesis of the System: Topic Selection, Architecture Drafting & Pure PHP Foundations', 'August 26, 2026', 'Kicked off on topic selection day—immediately drafted the architecture, cataloged requirements, explored UI inspirations, and began non-stop coding during every free hour adhering strictly to pure PHP with zero static HTML.', '{"id":"day-01","sprint_number":"01","sprint_badge":"DAY 01 · TOPIC SELECTION & SYSTEM DRAFTING","title":"Genesis of the System: Topic Selection, Architecture Drafting & Pure PHP Foundations","date":"August 26, 2026","read_time":"5 min read","author_name":"Alwinson Bustamante","author_role":"Lead Developer & System Architect","author_image":"assets/img/developers/BUSTAMANTE.jpg","summary_excerpt":"Kicked off on topic selection day—immediately drafted the architecture, cataloged requirements, explored UI inspirations, and began non-stop coding during every free hour adhering strictly to pure PHP with zero static HTML.","tags":["Topic Selection","System Blueprint","Modular PHP","Zero Static HTML"],"cover_image":"assets/img/devblog/day-01.jpg","full_story":"<p class=\'lead text-ink fw-semibold\'>Our journey began on August 26, 2026—the day our team picked the project topic for our COAL101 Web Systems and Technologies midterm lab project.</p><p>As soon as we chose the <strong>Campus Job Posting System</strong>, we didn\'t waste a single moment. We planned immediately, structured the project directory hierarchy, listed every functional module we would need, and researched modern design inspirations suited for a premier institutional portal.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-code-slash text-accent me-2\'></i>Strict Stack Compliance: Native PHP, No Raw HTML</h5><p>During our free time that day on campus, we started drafting the site. We strictly limited our stack to what our professor permitted: Native PHP, CSS, Bootstrap 5.3, and Vanilla JavaScript—with <strong>strictly no standalone HTML files</strong> as our professor instructed. Every page had to be dynamically composed via modular PHP components.</p><h5 class=\'fw-bold text-ink mt-4 mb-2\'><i class=\'bi bi-lightning-charge-fill text-accent me-2\'></i>Lead Developer Dedication</h5><p>As the lead of this development, I simply couldn\'t stop thinking about the system. I continued developing through another free period that same day and kept writing code up until we went home, determined to finish the foundational task.</p>","key_takeaways":["Selected the Campus Job Posting System topic and mapped all functional requirements.","Enforced pure Native PHP modular template architecture with zero static .html files.","Defined initial JSON datastore schemas for users, categories, jobs, and applications.","Developed continuously through campus free periods and after going home to build the skeleton."],"tech_stack":["Native PHP 8","Bootstrap 5.3","Modular Architecture","JSON Datastore Schema"]}', '2026-09-08 12:00:00') ON DUPLICATE KEY UPDATE `sprint_title`=VALUES(`sprint_title`);
